CREATE TABLE IF NOT EXISTS archive_settings (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL UNIQUE, managed_knowledge_base_id TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai', extraction_model_id TEXT NOT NULL DEFAULT '', extraction_version TEXT NOT NULL DEFAULT '1.0', trash_retention_days INTEGER NOT NULL DEFAULT 30, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS archive_import_batches (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, user_id TEXT NOT NULL, total INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'processing', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_archive_import_batches_tenant ON archive_import_batches(tenant_id, created_at DESC);
CREATE TABLE IF NOT EXISTS archive_customers (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, name TEXT NOT NULL, normalized TEXT NOT NULL, aliases TEXT NOT NULL DEFAULT '[]', notes TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_archive_customers_normalized ON archive_customers(tenant_id, normalized);
CREATE TABLE IF NOT EXISTS archive_documents (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, import_batch_id TEXT, knowledge_id TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, file_name TEXT NOT NULL, file_type TEXT NOT NULL, file_size INTEGER NOT NULL DEFAULT 0, file_hash TEXT NOT NULL, file_path TEXT NOT NULL, document_type TEXT NOT NULL DEFAULT 'other', business_type TEXT NOT NULL DEFAULT 'other', customer_id TEXT, agreement_number TEXT NOT NULL DEFAULT '', signed_at DATETIME, effective_at DATETIME, expires_at DATETIME, returned_at DATETIME, renewed_at DATETIME, amount REAL NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT '', extracted_text TEXT NOT NULL DEFAULT '', extracted_fields TEXT NOT NULL DEFAULT '{}', metadata TEXT NOT NULL DEFAULT '{}', extraction_status TEXT NOT NULL DEFAULT 'uploading', extraction_version TEXT NOT NULL DEFAULT '1.0', error_message TEXT NOT NULL DEFAULT '', archived_at DATETIME, trashed_at DATETIME, created_by TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_archive_documents_hash ON archive_documents(tenant_id, file_hash) WHERE trashed_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_archive_documents_listing ON archive_documents(tenant_id, trashed_at, archived_at, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_archive_documents_agreement ON archive_documents(tenant_id, agreement_number);
CREATE TABLE IF NOT EXISTS archive_assets (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, name TEXT NOT NULL DEFAULT '', model TEXT NOT NULL DEFAULT '', serial_number TEXT NOT NULL DEFAULT '', quantity INTEGER NOT NULL DEFAULT 1, is_quantity_only INTEGER NOT NULL DEFAULT 0, customer_id TEXT, business_type TEXT NOT NULL DEFAULT 'other', status TEXT NOT NULL DEFAULT 'unknown', status_override INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_archive_assets_sn ON archive_assets(tenant_id, serial_number) WHERE serial_number <> '';
CREATE INDEX IF NOT EXISTS idx_archive_assets_model ON archive_assets(tenant_id, model);
CREATE TABLE IF NOT EXISTS archive_document_assets (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, document_id TEXT NOT NULL, asset_id TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, link_status TEXT NOT NULL DEFAULT 'confirmed', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_archive_document_assets_pair ON archive_document_assets(document_id, asset_id);
CREATE TABLE IF NOT EXISTS archive_document_links (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, from_document_id TEXT NOT NULL, to_document_id TEXT NOT NULL, relation TEXT NOT NULL, link_status TEXT NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_archive_document_links_from ON archive_document_links(tenant_id, from_document_id);
CREATE INDEX IF NOT EXISTS idx_archive_document_links_to ON archive_document_links(tenant_id, to_document_id);
CREATE TABLE IF NOT EXISTS archive_field_evidence (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, document_id TEXT NOT NULL, knowledge_id TEXT NOT NULL DEFAULT '', chunk_id TEXT NOT NULL DEFAULT '', field_name TEXT NOT NULL, value TEXT NOT NULL, confidence REAL NOT NULL DEFAULT 0, quote TEXT NOT NULL DEFAULT '', locator_kind TEXT NOT NULL DEFAULT 'text', locator TEXT NOT NULL DEFAULT '{}', source_start INTEGER NOT NULL DEFAULT 0, source_end INTEGER NOT NULL DEFAULT 0, is_manual INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_archive_field_evidence_document ON archive_field_evidence(tenant_id, document_id, field_name);
CREATE INDEX IF NOT EXISTS idx_archive_field_evidence_source ON archive_field_evidence(tenant_id, knowledge_id, chunk_id);
CREATE TABLE IF NOT EXISTS archive_reminders (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, document_id TEXT, customer_id TEXT, asset_id TEXT, assignee_id TEXT NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', rule TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'draft', confidence REAL NOT NULL DEFAULT 0, due_at DATETIME, snoozed_until DATETIME, last_occurrence_at DATETIME, created_by TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_archive_reminders_due ON archive_reminders(tenant_id, status, due_at);
CREATE TABLE IF NOT EXISTS archive_reminder_occurrences (id TEXT PRIMARY KEY, reminder_id TEXT NOT NULL, tenant_id INTEGER NOT NULL, fingerprint TEXT NOT NULL UNIQUE, due_at DATETIME NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS archive_notifications (id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, user_id TEXT NOT NULL, reminder_id TEXT, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', read_at DATETIME, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_archive_notifications_user ON archive_notifications(tenant_id, user_id, read_at, created_at DESC);
